INSERT INTO categories (id, name, slug, description, image_url) VALUES
(1, 'Silk Sarees', 'sarees', 'Exquisite handcrafted traditional pure silk sarees with rich zari borders and authentic weaving heritage.', 'https://images.unsplash.com/photo-1610030469983-98e550d6193c?auto=format&fit=crop&w=800&q=80'),
(2, 'Makeup Products', 'makeup', 'Premium beauty essentials, organic bridal cosmetics, and vibrant pigments formulated for long-lasting radiant glow.', 'https://images.unsplash.com/photo-1522335789203-aabd1fc54bc9?auto=format&fit=crop&w=800&q=80'),
(3, 'Bangles', 'bangles', 'Intricately handcrafted bridal, festive, and ethnic bangles adorned with kundan, pearls, and royal stone motifs.', 'https://images.unsplash.com/photo-1611591475871-331697203b9b?auto=format&fit=crop&w=800&q=80')
INSERT INTO products (id, category_id, name, slug, description, price, compare_at_price, sku, material, color, size_or_dimension, rating, review_count, is_featured, is_trending, image_url, gallery_urls) VALUES
(1, 1, 'Royal Crimson Banarasi Katan Silk Saree', 'royal-crimson-banarasi-katan-silk-saree', 'Pure handwoven Banarasi Katan silk in deep crimson red featuring intricate gold and silver floral kadwa jaal motifs and an ornate pallu.', 18499.00, 22999.00, 'SAR-BAN-001', 'Pure Katan Silk', 'Crimson Red', '6.3 Meters with Blouse', 4.9, 128, true, true, 'https://images.unsplash.com/photo-1610030469983-98e550d6193c?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1610030469983-98e550d6193c?auto=format&fit=crop&w=800&q=80']),
(2, 1, 'Temple Gold Kanchipuram Bridal Silk Saree', 'temple-gold-kanchipuram-bridal-silk-saree', 'Traditional South Indian bridal Kanchipuram heavy silk saree featuring genuine 2-gram gold zari korvai borders depicting temple towers.', 26500.00, 31000.00, 'SAR-KAN-002', 'Pure Mulberry Silk', 'Mustard Gold', '6.3 Meters with Blouse', 5.0, 94, true, true, 'https://images.unsplash.com/photo-1583391733956-3750e0ff4e8b?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1583391733956-3750e0ff4e8b?auto=format&fit=crop&w=800&q=80']),
(3, 1, 'Royal Navy Mysore Crepe Silk Saree', 'royal-navy-mysore-crepe-silk-saree', 'Lightweight yet lustrous original KSIC Mysore silk saree in royal navy blue enriched with pure zari lines and rich contrast pallu.', 12200.00, 14500.00, 'SAR-MYS-003', 'Mysore Crepe Silk', 'Navy Blue', '6.2 Meters with Blouse', 4.8, 76, true, false, 'https://images.unsplash.com/photo-1617627143750-d86bc21e42bb?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1617627143750-d86bc21e42bb?auto=format&fit=crop&w=800&q=80']),
(4, 1, 'Pastel Mint Sheer Organza Silk Saree', 'pastel-mint-sheer-organza-silk-saree', 'Delicate organza silk draped in pastel mint adorned with hand-painted floral motifs and fine scallop zari threadwork borders.', 9800.00, 11500.00, 'SAR-ORG-004', 'Organza Silk', 'Mint Green', '6.3 Meters with Blouse', 4.7, 52, true, true, 'https://images.unsplash.com/photo-1609357605129-26f69add5d6e?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1609357605129-26f69add5d6e?auto=format&fit=crop&w=800&q=80']),
(5, 1, 'Emerald Green Paithani Silk Saree', 'emerald-green-paithani-silk-saree', 'Authentic Maharashtra Yeola Paithani saree with traditional mor-bangadi (peacock in bangle) motifs and a kaleidoscopic zari pallu.', 21500.00, 25000.00, 'SAR-PAI-005', 'Paithani Pure Silk', 'Emerald Green', '6.3 Meters with Blouse', 4.9, 63, false, true, 'https://images.unsplash.com/photo-1610030469983-98e550d6193c?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1610030469983-98e550d6193c?auto=format&fit=crop&w=800&q=80']),
(6, 1, 'Blush Peach Chanderi Tissue Silk Saree', 'blush-peach-chanderi-tissue-silk-saree', 'Subtle shimmer Chanderi silk with delicate golden tissue weft, small ashrafi butties, and feather-soft traditional drape.', 8400.00, 9900.00, 'SAR-CHA-006', 'Chanderi Silk', 'Blush Peach', '6.2 Meters with Blouse', 4.6, 41, false, false, 'https://images.unsplash.com/photo-1583391733956-3750e0ff4e8b?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1583391733956-3750e0ff4e8b?auto=format&fit=crop&w=800&q=80']),
(7, 1, 'Wild Golden Tussar Silk Saree', 'wild-golden-tussar-silk-saree', 'Natural textured raw Tussar silk in earthy honey-beige featuring hand block tribal prints and kantha embroidery work.', 10500.00, 12000.00, 'SAR-TUS-007', 'Tussar Silk', 'Honey Beige', '6.3 Meters with Blouse', 4.7, 39, false, false, 'https://images.unsplash.com/photo-1617627143750-d86bc21e42bb?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1617627143750-d86bc21e42bb?auto=format&fit=crop&w=800&q=80']),
(8, 1, 'Double Ikkat Patan Patola Silk Saree', 'double-ikkat-patan-patola-silk-saree', 'Prestigious double-ikkat geometric silk saree crafted by master weavers using resist-dye techniques and vibrant natural dyes.', 38000.00, 44000.00, 'SAR-PAT-008', 'Pure Silk Ikkat', 'Multicolor Crimson', '6.3 Meters with Blouse', 5.0, 22, true, false, 'https://images.unsplash.com/photo-1609357605129-26f69add5d6e?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1609357605129-26f69add5d6e?auto=format&fit=crop&w=800&q=80']),
(9, 1, 'Midnight Black Banarasi Georgette Saree', 'midnight-black-banarasi-georgette-saree', 'Lightweight pure Banarasi khaddi georgette in jet black with antique copper zari jaal and scalloped designer borders.', 15200.00, 17500.00, 'SAR-BAN-009', 'Khaddi Georgette Silk', 'Midnight Black', '6.3 Meters with Blouse', 4.8, 88, false, true, 'https://images.unsplash.com/photo-1610030469983-98e550d6193c?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1610030469983-98e550d6193c?auto=format&fit=crop&w=800&q=80']),
(10, 1, 'Sunburst Yellow Kanchipuram Brocade Saree', 'sunburst-yellow-kanchipuram-brocade-saree', 'Vibrant festive yellow Kanchi pattu with contrasting rani pink zari border depicting peacock and chakram motifs.', 22000.00, 26000.00, 'SAR-KAN-010', 'Pure Kanchipuram Silk', 'Sunburst Yellow', '6.3 Meters with Blouse', 4.9, 71, false, false, 'https://images.unsplash.com/photo-1583391733956-3750e0ff4e8b?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1583391733956-3750e0ff4e8b?auto=format&fit=crop&w=800&q=80']),
(11, 1, 'Wine Plum Uppada Jamdani Silk Saree', 'wine-plum-uppada-jamdani-silk-saree', 'Featherlight Uppada silk woven with Jamdani non-mechanical loom weaving featuring delicate floral bouquets and fine zari trims.', 16400.00, 19000.00, 'SAR-UPP-011', 'Uppada Silk', 'Wine Plum', '6.3 Meters with Blouse', 4.8, 34, false, false, 'https://images.unsplash.com/photo-1617627143750-d86bc21e42bb?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1617627143750-d86bc21e42bb?auto=format&fit=crop&w=800&q=80']),
(12, 1, 'Rani Pink Dharmavaram Wedding Saree', 'rani-pink-dharmavaram-wedding-saree', 'Traditional Andhra Dharmavaram broad border wedding saree with solid contrast pallu and heavy gold embossed zari panels.', 17900.00, 21000.00, 'SAR-DHA-012', 'Pure Silk', 'Rani Pink', '6.3 Meters with Blouse', 4.7, 47, false, true, 'https://images.unsplash.com/photo-1609357605129-26f69add5d6e?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1609357605129-26f69add5d6e?auto=format&fit=crop&w=800&q=80']),
(13, 1, 'Ivory Gold Muga Assam Silk Saree', 'ivory-gold-muga-assam-silk-saree', 'Rare wild Assam golden Muga silk known for its natural golden sheen, durability, and traditional mekhala motifs.', 29500.00, 34000.00, 'SAR-MUG-013', 'Assam Muga Silk', 'Natural Golden Ivory', '6.3 Meters with Blouse', 4.9, 19, false, false, 'https://images.unsplash.com/photo-1610030469983-98e550d6193c?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1610030469983-98e550d6193c?auto=format&fit=crop&w=800&q=80']),
(14, 1, 'Lavender Lilac Soft Silk Saree', 'lavender-lilac-soft-silk-saree', 'Contemporary comfort soft silk saree in serene pastel lilac, designed with minimal silver zari polka buttas and sleek piping.', 7999.00, 9500.00, 'SAR-SOF-014', 'Soft Mulberry Silk', 'Lavender Lilac', '6.2 Meters with Blouse', 4.6, 62, false, false, 'https://images.unsplash.com/photo-1583391733956-3750e0ff4e8b?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1583391733956-3750e0ff4e8b?auto=format&fit=crop&w=800&q=80']),
(15, 1, 'Maroon Gadwal Handloom Silk Saree', 'maroon-gadwal-handloom-silk-saree', 'Traditional Gadwal saree woven with a pure cotton-silk body coupled with attached heavy pure silk kuttu borders and rich pallu.', 13500.00, 15800.00, 'SAR-GAD-015', 'Gadwal Silk', 'Deep Maroon', '6.3 Meters with Blouse', 4.8, 38, false, false, 'https://images.unsplash.com/photo-1617627143750-d86bc21e42bb?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1617627143750-d86bc21e42bb?auto=format&fit=crop&w=800&q=80']),
(16, 1, 'Turquoise Baluchari Mythological Silk Saree', 'turquoise-baluchari-mythological-silk-saree', 'West Bengal Bishnupur Baluchari silk featuring elaborate narrative scenes from the Ramayana woven across the pallu in resham thread.', 19800.00, 23000.00, 'SAR-BAL-016', 'Baluchari Silk', 'Turquoise Blue', '6.3 Meters with Blouse', 4.9, 29, false, true, 'https://images.unsplash.com/photo-1609357605129-26f69add5d6e?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1609357605129-26f69add5d6e?auto=format&fit=crop&w=800&q=80']),
(17, 1, 'Olive Green Pochampally Ikkat Silk Saree', 'olive-green-pochampally-ikkat-silk-saree', 'Telangana Pochampally silk saree in contemporary olive green featuring geometric diamond ikkat tie-dye patterns and dual-tone borders.', 11800.00, 13900.00, 'SAR-POC-017', 'Pochampally Silk', 'Olive Green', '6.2 Meters with Blouse', 4.7, 45, false, false, 'https://images.unsplash.com/photo-1610030469983-98e550d6193c?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1610030469983-98e550d6193c?auto=format&fit=crop&w=800&q=80']),
(18, 1, 'Coral Rose Maheshwari Silk Cotton Saree', 'coral-rose-maheshwari-silk-cotton-saree', 'Historic Maheshwari craft originating from the Narmada riverbank with reversible bugdi borders and lightweight glossy weave.', 6900.00, 8200.00, 'SAR-MAH-018', 'Maheshwari Silk', 'Coral Rose', '6.2 Meters with Blouse', 4.5, 54, false, false, 'https://images.unsplash.com/photo-1583391733956-3750e0ff4e8b?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1583391733956-3750e0ff4e8b?auto=format&fit=crop&w=800&q=80']),
(19, 1, 'Deep Ruby Tanchoi Banarasi Silk Saree', 'deep-ruby-tanchoi-banarasi-silk-saree', 'Satin-finish Banarasi Tanchoi saree featuring all-over embossed floral vines woven with colorful fine silk weft without floating threads.', 14600.00, 17000.00, 'SAR-TAN-019', 'Banarasi Tanchoi Silk', 'Deep Ruby', '6.3 Meters with Blouse', 4.8, 33, false, false, 'https://images.unsplash.com/photo-1617627143750-d86bc21e42bb?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1617627143750-d86bc21e42bb?auto=format&fit=crop&w=800&q=80']),
(20, 1, 'Vintage Gold Kanjeevaram Tissue Silk Saree', 'vintage-gold-kanjeevaram-tissue-silk-saree', 'Opulent all-over gold metallic tissue silk with grand floral kalasams on the pallu, ideal for traditional bride ceremonies.', 32000.00, 37500.00, 'SAR-KAN-020', 'Gold Tissue Silk', 'Vintage Antique Gold', '6.3 Meters with Blouse', 5.0, 48, false, true, 'https://images.unsplash.com/photo-1609357605129-26f69add5d6e?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1609357605129-26f69add5d6e?auto=format&fit=crop&w=800&q=80']);
INSERT INTO products (id, category_id, name, slug, description, price, compare_at_price, sku, material, color, size_or_dimension, rating, review_count, is_featured, is_trending, image_url, gallery_urls) VALUES
(21, 2, 'Velvet Matte Long-Wear Lipstick - Royal Crimson', 'velvet-matte-longwear-lipstick-crimson', 'Ultra-pigmented, transfer-proof matte liquid lipstick enriched with vitamin E and jojoba oil for 16-hour hydration and comfortable wear.', 1199.00, 1499.00, 'MKP-LIP-021', 'Liquid Matte Finish', 'Royal Crimson', '5.5 ml', 4.9, 310, true, true, 'https://images.unsplash.com/photo-1586495777744-4413f21062fa?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1586495777744-4413f21062fa?auto=format&fit=crop&w=800&q=80']),
(22, 2, 'Luminous Radiance Serum Foundation', 'luminous-radiance-serum-foundation', 'Breathable medium-to-full coverage liquid foundation infused with hyaluronic acid and niacinamide for an all-day luminous dewy finish.', 1850.00, 2200.00, 'MKP-FND-022', 'Liquid Serum Foundation', 'Warm Honey', '30 ml', 4.8, 245, true, true, 'https://images.unsplash.com/photo-1522335789203-aabd1fc54bc9?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1522335789203-aabd1fc54bc9?auto=format&fit=crop&w=800&q=80']),
(23, 2, 'Flawless Finish Oil-Control Compact Powder', 'flawless-finish-compact-powder', 'Micro-milled silky mineral pressed powder that sets base makeup, blurs pores, and controls excess sebum with SPF 25 protection.', 899.00, 1100.00, 'MKP-CMP-023', 'Mineral Pressed Powder', 'Natural Beige', '9 g', 4.7, 180, true, false, 'https://images.unsplash.com/photo-1596462502278-27bfdc403348?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1596462502278-27bfdc403348?auto=format&fit=crop&w=800&q=80']),
(24, 2, '24-Hour Waterproof Jet Black Kohl Eyeliner', '24h-waterproof-kohl-eyeliner', 'Intense carbon black smudge-proof kajal pencil formulated with almond oil and herbal extracts for deep waterline definition.', 499.00, 650.00, 'MKP-EYE-024', 'Creamy Kohl Pencil', 'Jet Black', '0.35 g', 4.9, 520, true, true, 'https://images.unsplash.com/photo-1512496015851-a90fb38ba796?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1512496015851-a90fb38ba796?auto=format&fit=crop&w=800&q=80']),
(25, 2, 'Silk Blossom Dual-Tone Baked Blush', 'silk-blossom-baked-blush', 'Baked marble powder blush offering a silky swirl of soft rose and subtle champagne shimmer to enhance cheek contours effortlessly.', 950.00, 1200.00, 'MKP-BLS-025', 'Baked Powder', 'Rose Champagne', '7.5 g', 4.8, 142, false, true, 'https://images.unsplash.com/photo-1522335789203-aabd1fc54bc9?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1522335789203-aabd1fc54bc9?auto=format&fit=crop&w=800&q=80']),
(26, 2, 'Volumizing & Curling Lash Lift Mascara', 'volumizing-lash-lift-mascara', 'Hourglass wand mascara delivering 3x lash multiplication, clump-free curl retention, and water-resistant wear throughout the day.', 799.00, 999.00, 'MKP-MAS-026', 'Waterproof Mascara', 'Midnight Onyx', '10 ml', 4.6, 198, false, false, 'https://images.unsplash.com/photo-1512496015851-a90fb38ba796?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1512496015851-a90fb38ba796?auto=format&fit=crop&w=800&q=80']),
(27, 2, 'Pore-Refining Mattifying Face Primer', 'pore-refining-mattifying-primer', 'Silky silicone-free primer that creates a smooth canvas, controls oil in the T-zone, and extends makeup durability for up to 18 hours.', 1150.00, 1400.00, 'MKP-PRM-027', 'Silky Gel Base', 'Translucent', '25 ml', 4.7, 115, false, false, 'https://images.unsplash.com/photo-1596462502278-27bfdc403348?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1596462502278-27bfdc403348?auto=format&fit=crop&w=800&q=80']),
(28, 2, 'Royal Sunset 18-Shade Eyeshadow Palette', 'royal-sunset-eyeshadow-palette', 'A luxury mix of warm copper shimmers, velvety jewel tones, and butter-smooth matte neutrals designed for festive and bridal eye looks.', 2400.00, 2900.00, 'MKP-EYE-028', 'Powder Shadow Palette', 'Sunset Gold & Berry', '22 g', 4.9, 165, true, true, 'https://images.unsplash.com/photo-1586495777744-4413f21062fa?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1586495777744-4413f21062fa?auto=format&fit=crop&w=800&q=80']),
(29, 2, 'High-Definition Camouflage Liquid Concealer', 'hd-camouflage-liquid-concealer', 'Crease-proof, high-coverage concealer that brightens under-eyes, conceals hyperpigmentation, and blends seamlessly into skin.', 750.00, 950.00, 'MKP-CON-029', 'Liquid Concealer', 'Medium Almond', '6 ml', 4.7, 134, false, false, 'https://images.unsplash.com/photo-1522335789203-aabd1fc54bc9?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1522335789203-aabd1fc54bc9?auto=format&fit=crop&w=800&q=80']),
(30, 2, 'Golden Glow Liquid Illuminator Highlighter', 'golden-glow-liquid-highlighter', 'Concentrated strobe drops delivering a glass-skin, sun-drenched golden beam to high points of the face, collarbones, and decolletage.', 1250.00, 1500.00, 'MKP-HLT-030', 'Liquid Strobe Drop', 'Molten Gold', '15 ml', 4.8, 92, false, true, 'https://images.unsplash.com/photo-1596462502278-27bfdc403348?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1596462502278-27bfdc403348?auto=format&fit=crop&w=800&q=80']),
(31, 2, 'Ultra Hydrating Tinted Lip & Cheek Oil', 'hydrating-tinted-lip-cheek-oil', 'Non-sticky pH-activated oil glaze that reacts to individual skin chemistry to create a custom flush of sheer berry tint.', 850.00, 1050.00, 'MKP-LIP-031', 'Gel Lip Oil', 'Wild Berry Tint', '7 ml', 4.6, 88, false, false, 'https://images.unsplash.com/photo-1586495777744-4413f21062fa?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1586495777744-4413f21062fa?auto=format&fit=crop&w=800&q=80']),
(32, 2, 'Dewy Micro-Fine Hydrating Setting Spray', 'dewy-microfine-setting-spray', 'Weightless mist enriched with rosewater and aloe vera that locks makeup in place for 16 hours while preventing powdery cake-up.', 990.00, 1200.00, 'MKP-SET-032', 'Hydrating Facial Mist', 'Clear Mist', '100 ml', 4.8, 172, false, false, 'https://images.unsplash.com/photo-1512496015851-a90fb38ba796?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1512496015851-a90fb38ba796?auto=format&fit=crop&w=800&q=80']),
(33, 2, 'Defined Arch Micro Precision Brow Pencil', 'defined-arch-micro-brow-pencil', '0.5mm ultra-slim tip eyebrow pencil with built-in spoolie to draw hair-like strokes and shape polished arches naturally.', 599.00, 750.00, 'MKP-BRW-033', 'Waxy Micro Pencil', 'Dark Espresso', '0.08 g', 4.7, 104, false, false, 'https://images.unsplash.com/photo-1522335789203-aabd1fc54bc9?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1522335789203-aabd1fc54bc9?auto=format&fit=crop&w=800&q=80']),
(34, 2, 'Sun-Kissed Matte Bronzer Powder', 'sunkissed-matte-bronzer', 'Warm terracotta contour powder that sculpts cheekbones and adds natural warmth without muddy or orange undertones.', 920.00, 1150.00, 'MKP-BRZ-034', 'Pressed Velvet Powder', 'Deep Terracotta', '11 g', 4.7, 79, false, false, 'https://images.unsplash.com/photo-1596462502278-27bfdc403348?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1596462502278-27bfdc403348?auto=format&fit=crop&w=800&q=80']),
(35, 2, 'Satin Sheen Classic Crayon Lipstick - Nude Muse', 'satin-sheen-crayon-lipstick-nude', 'Buttery soft satin formula in universally flattering peachy nude, enriched with shea butter and argan oil.', 799.00, 999.00, 'MKP-LIP-035', 'Satin Crayon', 'Peachy Nude', '3.8 g', 4.8, 147, false, true, 'https://images.unsplash.com/photo-1586495777744-4413f21062fa?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1586495777744-4413f21062fa?auto=format&fit=crop&w=800&q=80']),
(36, 2, 'Color Correcting Skin Tone Balancing Palette', 'color-correcting-skin-palette', 'Five-shade cream corrector palette targeting redness, dark spots, dullness, and sallowness before foundation application.', 1100.00, 1350.00, 'MKP-COR-036', 'Cream Correctors', 'Multicolor Corrector', '12 g', 4.6, 68, false, false, 'https://images.unsplash.com/photo-1522335789203-aabd1fc54bc9?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1522335789203-aabd1fc54bc9?auto=format&fit=crop&w=800&q=80']),
(37, 2, 'Precision Felt-Tip Waterproof Liquid Liner', 'precision-liquid-felt-eyeliner', 'Calligraphy-inspired fine felt-tip eyeliner ensuring razor-sharp wings, quick drying, and carbon black finish.', 650.00, 800.00, 'MKP-EYE-037', 'Liquid Felt Liner', 'Pitch Black', '1.2 ml', 4.8, 215, false, false, 'https://images.unsplash.com/photo-1512496015851-a90fb38ba796?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1512496015851-a90fb38ba796?auto=format&fit=crop&w=800&q=80']),
(38, 2, 'Nourishing Berry Overnight Lip Sleeping Mask', 'nourishing-berry-lip-mask', 'Intensive leave-on balm with berry fruit complex that melts away dead skin cells and delivers supple plumpness by morning.', 699.00, 850.00, 'MKP-LIP-038', 'Balm Mask', 'Sweet Berry', '20 g', 4.9, 310, false, false, 'https://images.unsplash.com/photo-1586495777744-4413f21062fa?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1586495777744-4413f21062fa?auto=format&fit=crop&w=800&q=80']),
(39, 2, 'Luxury 8-Piece Vegan Synthetic Brush Set', 'luxury-vegan-makeup-brush-set', 'Handcrafted bamboo-handle brush collection with ultra-soft hypoallergenic bristles for foundation, powder, contour, and eye blending.', 1999.00, 2600.00, 'MKP-BRS-039', 'Synthetic Fiber & Bamboo', 'Rose Gold & Wood', '8 Pieces Kit', 4.8, 126, false, false, 'https://images.unsplash.com/photo-1522335789203-aabd1fc54bc9?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1522335789203-aabd1fc54bc9?auto=format&fit=crop&w=800&q=80']),
(40, 2, 'Sparkling Diamond Eye & Face Glitter Gel', 'sparkling-diamond-glitter-gel', 'Self-adhesive holographic glitter gel for celestial festive sparkles on eyelids, brows, and cheekbones without fallout.', 550.00, 700.00, 'MKP-GLT-040', 'Water-based Glitter Gel', 'Champagne Sparkle', '10 g', 4.7, 72, false, false, 'https://images.unsplash.com/photo-1596462502278-27bfdc403348?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1596462502278-27bfdc403348?auto=format&fit=crop&w=800&q=80']);
