(41, 3, 'Royal Kundan & Ruby Bridal Kada Set (Set of 2)', 'royal-kundan-ruby-bridal-kada', 'Opulent bridal kada handcrafted in brass with 22k antique gold plating, studded with uncut kundan stones and synthetic ruby cabochons.', 4899.00, 5999.00, 'BAN-KUN-041', 'Brass & 22K Gold Plated', 'Ruby Red & Gold', 'Size 2.6', 4.9, 114, true, true, 'https://images.unsplash.com/photo-1611591475871-331697203b9b?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1611591475871-331697203b9b?auto=format&fit=crop&w=800&q=80']),
(42, 3, 'Traditional 22K Gold Plated Filigree Bangles (Set of 4)', 'gold-plated-filigree-bangles-set-of-4', 'Graceful filigree lattice work bangles with delicate micro-pearl edging, suitable for daily festive elegance and temple visits.', 2450.00, 2999.00, 'BAN-GLD-042', 'Copper Alloy Gold Plated', 'Shining Gold', 'Size 2.4', 4.8, 98, true, false, 'https://images.unsplash.com/photo-1535632066927-ab7c9ab60908?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1535632066927-ab7c9ab60908?auto=format&fit=crop&w=800&q=80']),
(43, 3, 'Emerald Green Festive Glass Bangles (Set of 24)', 'emerald-green-festive-glass-bangles', 'Traditional chiming handcrafted Firozabad glass bangles in lustrous emerald green with subtle golden glitter lining.', 499.00, 699.00, 'BAN-GLS-043', 'Firozabad Glass', 'Emerald Green', 'Size 2.6', 4.7, 210, true, true, 'https://images.unsplash.com/photo-1605100804763-247f67b3557e?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1605100804763-247f67b3557e?auto=format&fit=crop&w=800&q=80']),
(44, 3, 'American Diamond Cubic Zirconia Sleek Bangles (Set of 2)', 'cubic-zirconia-sleek-bangles', 'Precision-crafted silver rhodium finished bangles encrusted with AAA grade baguette cut sparkling American diamonds.', 3200.00, 3900.00, 'BAN-STN-044', 'Rhodium Plated Silver Alloy', 'Sparkling Silver', 'Size 2.4', 4.9, 87, true, true, 'https://images.unsplash.com/photo-1611591475871-331697203b9b?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1611591475871-331697203b9b?auto=format&fit=crop&w=800&q=80']),
(45, 3, 'South Indian Temple Nakshi Antique Kada', 'south-indian-temple-nakshi-kada', 'Masterpiece single openable kada featuring divine Goddess Lakshmi motifs surrounded by peacocks in antique matte gold finish.', 3600.00, 4400.00, 'BAN-TMP-045', 'Brass Temple Jewelry', 'Matte Antique Gold', 'Adjustable Screw', 4.9, 65, false, true, 'https://images.unsplash.com/photo-1535632066927-ab7c9ab60908?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1535632066927-ab7c9ab60908?auto=format&fit=crop&w=800&q=80']),
(46, 3, 'Royal Velvet Touch Bridal Chooda Set (Set of 36)', 'royal-velvet-bridal-chooda-set', 'Complete North Indian wedding bridal chooda set combining deep crimson acrylic bangles with golden kundan studded latkans.', 4200.00, 5200.00, 'BAN-CHO-046', 'Acrylic & Velvet Finish', 'Crimson & Ivory', 'Size 2.6', 5.0, 78, true, false, 'https://images.unsplash.com/photo-1605100804763-247f67b3557e?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1605100804763-247f67b3557e?auto=format&fit=crop&w=800&q=80']),
(47, 3, 'Meenakari Peacock Hand-Painted Bangles (Set of 2)', 'meenakari-peacock-handpainted-bangles', 'Vibrant Jaipur meenakari enamel work depicting dancing peacocks in turquoise, cobalt, and gold leaf highlights.', 2100.00, 2600.00, 'BAN-MEE-047', 'Enamel on Brass', 'Turquoise & Royal Blue', 'Size 2.4', 4.8, 56, false, false, 'https://images.unsplash.com/photo-1611591475871-331697203b9b?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1611591475871-331697203b9b?auto=format&fit=crop&w=800&q=80']),
(48, 3, 'Pearlescent South Sea Cultured Pearl Bangles (Set of 4)', 'cultured-pearl-gold-bangles', 'Lustrous off-white button pearls individually strung on gold-plated sterling silver frames for understated timeless grace.', 5500.00, 6800.00, 'BAN-PRL-048', 'Cultured Pearl & Silver', 'Ivory Pearl & Gold', 'Size 2.6', 4.9, 43, false, false, 'https://images.unsplash.com/photo-1535632066927-ab7c9ab60908?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1535632066927-ab7c9ab60908?auto=format&fit=crop&w=800&q=80']),
(49, 3, 'Mustard Yellow Festive Glass Churi Set (Set of 24)', 'mustard-yellow-glass-churi-set', 'Traditional matte mustard glass bangles, ideal for Haldi celebrations and temple ceremonies with golden rim highlights.', 450.00, 600.00, 'BAN-GLS-049', 'Handblown Glass', 'Mustard Yellow', 'Size 2.4', 4.6, 92, false, false, 'https://images.unsplash.com/photo-1605100804763-247f67b3557e?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1605100804763-247f67b3557e?auto=format&fit=crop&w=800&q=80']),
(50, 3, 'Oxidised Silver Tribal Boho Kada', 'oxidised-silver-tribal-boho-kada', 'Statement tribal bohemian open cuff kada crafted with floral carvings, ghungroo bells, and antique black oxidation patina.', 1499.00, 1850.00, 'BAN-OXI-050', 'Oxidised German Silver', 'Antique Silver', 'Adjustable Free Size', 4.7, 130, false, true, 'https://images.unsplash.com/photo-1611591475871-331697203b9b?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1611591475871-331697203b9b?auto=format&fit=crop&w=800&q=80']),
(51, 3, 'Handcrafted Silk Thread Wrapped Bangles (Set of 6)', 'handcrafted-silk-thread-bangles', 'Lightweight wooden core bangles carefully wrapped in royal purple silk thread and finished with rhinestone chains.', 850.00, 1100.00, 'BAN-THR-051', 'Silk Thread & Rhinestone', 'Royal Purple', 'Size 2.6', 4.5, 49, false, false, 'https://images.unsplash.com/photo-1535632066927-ab7c9ab60908?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1535632066927-ab7c9ab60908?auto=format&fit=crop&w=800&q=80']),
(52, 3, 'Polki Diamond Heritage Jaali Bracelet Bangle', 'polki-diamond-heritage-jaali-bangle', 'Regal openable bracelet showcasing uncut polki diamonds set in 24k foil framework with intricate floral jaali cutouts.', 6800.00, 8200.00, 'BAN-POL-052', 'Polki Stone & Copper', 'Vintage Gold & Champagne', 'Size 2.6 with Clasp', 5.0, 37, false, true, 'https://images.unsplash.com/photo-1605100804763-247f67b3557e?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1605100804763-247f67b3557e?auto=format&fit=crop&w=800&q=80']),
(53, 3, 'Rose Gold Plated Minimalist Sleek Kada', 'rose-gold-minimalist-sleek-kada', 'Contemporary sleek oval hinged kada in 18k rose gold plating featuring subtle crystal pavé detailing on the crown.', 1899.00, 2400.00, 'BAN-ROZ-053', 'Stainless Steel 18K Rose Gold', 'Rose Gold', 'Free Size Hinged', 4.8, 105, false, false, 'https://images.unsplash.com/photo-1611591475871-331697203b9b?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1611591475871-331697203b9b?auto=format&fit=crop&w=800&q=80']),
(54, 3, 'Navratna Nine-Gemstone Spiritual Bangles (Set of 2)', 'navratna-gemstone-spiritual-bangles', 'Auspicious nine planetary gemstones set systematically on a rich gold carved band for spiritual balance and classic style.', 3999.00, 4800.00, 'BAN-NAV-054', 'Navratna Synthetic Gems & Brass', 'Multicolor Gems on Gold', 'Size 2.6', 4.8, 58, false, false, 'https://images.unsplash.com/photo-1535632066927-ab7c9ab60908?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1535632066927-ab7c9ab60908?auto=format&fit=crop&w=800&q=80']),
(55, 3, 'Clay Terracotta Hand-Painted Ethnic Bangles (Set of 4)', 'terracotta-handpainted-ethnic-bangles', 'Eco-friendly baked river clay bangles hand-painted with tribal motifs using vibrant earthy organic pigments.', 650.00, 850.00, 'BAN-TER-055', 'Natural Baked Clay', 'Earthy Ochre & Rust', 'Size 2.4', 4.6, 32, false, false, 'https://images.unsplash.com/photo-1605100804763-247f67b3557e?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1605100804763-247f67b3557e?auto=format&fit=crop&w=800&q=80']),
(56, 3, 'Royal Blue Matte Metal Bangles (Set of 36)', 'royal-blue-matte-metal-bangles', 'Sleek anodized lightweight metallic bangles in vibrant royal blue that do not chip or lose their satiny finish.', 399.00, 550.00, 'BAN-MET-056', 'Anodized Aluminum Alloy', 'Royal Cobalt Blue', 'Size 2.6', 4.4, 73, false, false, 'https://images.unsplash.com/photo-1611591475871-331697203b9b?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1611591475871-331697203b9b?auto=format&fit=crop&w=800&q=80']),
(57, 3, 'Kundan & Green Onyx Floral Bangles (Set of 2)', 'kundan-green-onyx-floral-bangles', 'Flawlessly set jadau kundan floral patterns flanked by deep green onyx droplets, capturing royal Rajasthani court jewelry.', 4600.00, 5600.00, 'BAN-ONY-057', 'Brass & Onyx Gemstones', 'Deep Green & White Kundan', 'Size 2.6', 4.9, 51, false, false, 'https://images.unsplash.com/photo-1535632066927-ab7c9ab60908?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1535632066927-ab7c9ab60908?auto=format&fit=crop&w=800&q=80']),
(58, 3, 'Bridal Red Lac Handcrafted Bangles (Set of 8)', 'bridal-red-lac-handcrafted-bangles', 'Traditional purified natural lac bangles from Jaipur studded with shimmering mirrors, zircon stones, and gold zari thread rings.', 1750.00, 2200.00, 'BAN-LAC-058', 'Pure Natural Lac', 'Bridal Scarlet Red', 'Size 2.4', 4.7, 61, false, false, 'https://images.unsplash.com/photo-1605100804763-247f67b3557e?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1605100804763-247f67b3557e?auto=format&fit=crop&w=800&q=80']),
(59, 3, 'Ghungroo Antique Brass Fusion Kada', 'ghungroo-antique-brass-fusion-kada', 'Musical jingling brass kada with dual rows of tiny acoustic ghungroo bells, bringing traditional rhythm to dance and festivities.', 1350.00, 1700.00, 'BAN-GHU-059', 'Solid Cast Brass', 'Antique Brass Gold', 'Size 2.6 Openable', 4.7, 84, false, false, 'https://images.unsplash.com/photo-1611591475871-331697203b9b?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1611591475871-331697203b9b?auto=format&fit=crop&w=800&q=80']),
(60, 3, 'Solitaire Moissanite High-End Tennis Bracelet Bangle', 'moissanite-tennis-bracelet-bangle', 'Luxury 3mm D-Color VVS1 certified Moissanite stones bezel-set in platinum-plated sterling silver with double safety deployment latch.', 8900.00, 11500.00, 'BAN-MOI-060', '925 Sterling Silver Platinum Plated', 'D-Color Brilliant White', 'Size 2.4 Box Clasp', 5.0, 42, false, true, 'https://images.unsplash.com/photo-1611591475871-331697203b9b?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1611591475871-331697203b9b?auto=format&fit=crop&w=800&q=80']);
