-- =============================================================================
-- Database Seed Data
-- Traditional Fashion & Beauty Store
-- 3 Categories, 60 Total Products (20 Sarees, 20 Makeup, 20 Bangles), Inventory
-- =============================================================================

-- 1. Insert Categories
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description;

SELECT setval('categories_id_seq', (SELECT MAX(id) FROM categories));

-- 2. Insert 20 Silk Sarees (Category ID: 1)

-- 3. Insert 20 Makeup Products (Category ID: 2)

-- 4. Insert 20 Bangles (Category ID: 3)

SELECT setval('products_id_seq', (SELECT MAX(id) FROM products));

-- 5. Insert Inventory records for all 60 products
SELECT id, (20 + (id % 30)), 5 FROM products
ON CONFLICT (product_id) DO UPDATE SET stock_quantity = EXCLUDED.stock_quantity;

-- 6. Insert Sample Customer
ON CONFLICT (id) DO NOTHING;

SELECT setval('customers_id_seq', (SELECT MAX(id) FROM customers));

-- 7. Insert Sample Order
ON CONFLICT (id) DO NOTHING;

SELECT setval('orders_id_seq', (SELECT MAX(id) FROM orders));

-- 8. Insert Sample Order Items
ON CONFLICT (id) DO NOTHING;

SELECT setval('order_items_id_seq', (SELECT MAX(id) FROM order_items));
